var SCENARIOS = [

/* ============ SCENARIO 1: HL7 ORU FILING FAILURE ============ */
{
id:"oru", sev:1, tag:"Interfaces · Beaker → ClinDoc",
title:"The Morning the Lab Results Stopped Filing",
sub:"HL7 ORU results from Beaker (LIS) failing to file into the Epic chart. Physicians are rounding blind. You are the on-call analyst — every choice has a patient-safety cost.",
chips:["SEV / P1","HL7 v2 · ORU^R01","Epic Bridges","Change control","Patient safety"],
ticket:{num:"INC0482913",sev:"P1 — CRITICAL",sevc:"s1",fields:[["Opened","Mon 07:12 AM"],["Caller","Charge RN, D2 Med/Surg"],["Assignment group","Clinical Informatics — Interfaces"],["Configuration item","IFC-BEAKER-ORU-IN"]],
desc:"\"Morning labs drawn at 0500 are resulted in the lab system but <em>nothing is showing in the patient charts</em>. Physicians are rounding now and can't see BMPs or troponins. Multiple units reporting the same thing. Lab says results left their system fine.\""},
phases:[
{tag:"Phase 1 — Triage",title:"07:42 — the ticket lands in your queue",
body:"<p class=\"body\">You've just sat down with coffee. The P1 pager fires. Rounding teams are blind to morning labs across <strong>multiple units</strong> — this is a patient-safety event in progress, not just an IT annoyance. The clock on your SLA reads 48 minutes.</p>",
q:"What's your first move?",
opts:[
{t:"Restart the inbound interface immediately. Fastest way to clear whatever is stuck and get results flowing again.",c:0},
{t:"Acknowledge the ticket, post an initial comms note, then pull up interface monitoring to confirm scope before touching anything.",c:1},
{t:"Escalate straight to Epic Technical Services — a filing failure this broad is probably a vendor-level defect.",c:0}],
good:"<span class='fb-tag'>Correct — verify before you act</span><p><strong>Scope first, comms early.</strong> A blind restart on a running interface destroys diagnostic state and risks message loss — and you don't yet know if this is one unit or the whole enterprise. Acknowledging the ticket and posting an initial status note also starts the clinical communication chain: nursing leadership needs to know results are delayed so units fall back to calling the lab for criticals.</p>",
bad:"<span class='fb-tag'>Not the strongest move</span><p>Restarting a <strong>running</strong> interface rarely fixes a filing problem and can lose in-flight messages. Escalating to the vendor before you've looked at your own monitoring wastes the minutes when you're best positioned to act. The strong first move: acknowledge, communicate, then <strong>confirm scope in monitoring</strong> before touching anything.</p>",
nxt:"Continue to monitoring →"},
{tag:"Phase 2 — Scope",title:"07:47 — the interface dashboard",
body:"<p class=\"body\">You open the interface engine console for the Beaker inbound result feed. The picture is immediate — and ugly.</p><div class=\"term\"><div class=\"term-bar\"><span class=\"dot r\"></span><span class=\"dot y\"></span><span class=\"dot g\"></span><span class=\"term-title\">bridges-console — IFC-BEAKER-ORU-IN</span></div><div class=\"term-body\"><span class=\"tk-p\">$</span> ifc status --interface BEAKER-ORU-IN --since 04:00\n\nINTERFACE        DIR   STATE     RECV    FILED   <span class=\"tk-e\">ERROR</span>\nBEAKER-ORU-IN    IN    <span class=\"tk-ok\">RUNNING</span>   1,412   87      <span class=\"tk-e\">1,325</span>\n\n<span class=\"tk-d\">hourly breakdown:</span>\n 04:00-05:00   recv 210   filed 210   err <span class=\"tk-ok\">0</span>\n 05:00-06:00   recv 388   filed  61   err <span class=\"tk-e\">327</span>   <span class=\"tk-w\">◀ degradation begins 05:12</span>\n 06:00-07:00   recv 402   filed  14   err <span class=\"tk-e\">388</span>\n 07:00-07:47   recv 412   filed   2   err <span class=\"tk-e\">410</span>\n\n<span class=\"tk-w\">⚠ error queue depth: 1,325 and climbing</span>\n<span class=\"tk-d\">last successful bulk filing: 05:11:48</span></div></div><p class=\"body\">The interface is <strong>running</strong> — messages are arriving. They're just failing to file, and it started abruptly at 05:12. This is not a connectivity problem.</p>",
q:"Next step?",
opts:[
{t:"Fail over to the backup interface node — the primary node is clearly unhealthy.",c:0},
{t:"Purge the error queue so new messages can process cleanly, then monitor.",c:0},
{t:"Open the error queue and inspect the actual failed messages — the error text will tell you why filing is rejected.",c:1}],
good:"<span class='fb-tag'>Correct — the error text is the evidence</span><p>The interface is RUNNING and receiving — connectivity is fine, so failover solves nothing. And purging the error queue would <strong>permanently discard 1,325 patient results</strong>. Deferred messages are recoverable; purged ones are not. The failed messages themselves will tell you exactly why filing is rejected.</p>",
bad:"<span class='fb-tag'>Careful — that path loses data or time</span><p>Failover addresses node health, but the node is healthy — messages arrive fine, they fail at <strong>filing logic</strong>. And purging the error queue permanently discards 1,325 patient results; deferred messages are recoverable, purged ones are gone. The right move is to read the failed messages — the error text is your evidence.</p>",
nxt:"Inspect a failed message →"},
{tag:"Phase 3 — Message inspection",title:"07:53 — reading the HL7",
body:"<p class=\"body\">You pull the most recent failed message. The filing error is consistent across all 1,325 of them:</p><div class=\"term\"><div class=\"term-bar\"><span class=\"dot r\"></span><span class=\"dot y\"></span><span class=\"dot g\"></span><span class=\"term-title\">error-queue — message 1325 of 1325</span></div><div class=\"term-body\"><span class=\"tk-e\">FILING ERROR:</span> Unable to file result — no matching order found\nfor filler order number <span class=\"tk-hl\">SHCB-20260705-000841</span>\n<span class=\"tk-d\">disposition: DEFERRED · retries: 3 · patient MRN verified ✓</span></div></div><p class=\"body\">Here is the raw ORU^R01 (identifiers synthetic). <strong>Click any segment</strong> to see what it does — then decide which field holds the clue.</p><div class=\"term\"><div class=\"term-bar\"><span class=\"dot r\"></span><span class=\"dot y\"></span><span class=\"dot g\"></span><span class=\"term-title\">ORU^R01 — raw message</span></div><div class=\"hl7\">\n<span class=\"seg\" data-note=\"n-msh\"><span class=\"sid\">MSH</span>|^~\\&amp;|BEAKER|SHC_LAB|EPIC|SHC|20260705075201||ORU^R01|8842317|P|2.5.1</span>\n<div class=\"seg-note\" id=\"n-msh\"><b>MSH — message header.</b> Sending app (BEAKER), receiving app (EPIC), timestamp, message type ORU^R01 = unsolicited observation result. Nothing abnormal here.</div>\n<span class=\"seg\" data-note=\"n-pid\"><span class=\"sid\">PID</span>|1||E100482913^^^SHC^MRN||SIMPATIENT^TEST^A||19581103|M</span>\n<div class=\"seg-note\" id=\"n-pid\"><b>PID — patient identification.</b> MRN matched a valid patient record — the error log confirmed patient lookup succeeded. Patient matching is not the failure point.</div>\n<span class=\"seg\" data-note=\"n-pv1\"><span class=\"sid\">PV1</span>|1|I|D2^D204^A|||||||MED</span>\n<div class=\"seg-note\" id=\"n-pv1\"><b>PV1 — patient visit.</b> Inpatient, unit D2, bed D204-A. Consistent with the reporting units. Contextual, not causal.</div>\n<span class=\"seg flag\" data-note=\"n-orc\"><span class=\"sid\">ORC</span>|RE|ORD8834412^EPC|<span class=\"tk-hl\">SHCB-20260705-000841</span>^BEAKER</span>\n<div class=\"seg-note\" id=\"n-orc\"><b>ORC — common order.</b> ORC-2 is the placer order number (Epic's ID for the order it placed). ORC-3 is the filler order number — the lab system's own ID, which Epic uses to match the result back to the original order. Look closely at that filler ID format.</div>\n<span class=\"seg flag\" data-note=\"n-obr\"><span class=\"sid\">OBR</span>|1|ORD8834412^EPC|<span class=\"tk-hl\">SHCB-20260705-000841</span>^BEAKER|BMP^Basic metabolic panel</span>\n<div class=\"seg-note\" id=\"n-obr\"><b>OBR — observation request.</b> Repeats placer (OBR-2) and filler (OBR-3) order numbers plus the test. Yesterday's successful messages carried filler IDs like <b>SHC-20260704-002210</b>. Today's carry <b>SHCB-</b>. The prefix changed.</div>\n<span class=\"seg\" data-note=\"n-obx\"><span class=\"sid\">OBX</span>|1|NM|2160-0^Creatinine^LN||1.1|mg/dL|0.7-1.3|N|||F</span>\n<div class=\"seg-note\" id=\"n-obx\"><b>OBX — observation result.</b> The actual value: creatinine 1.1 mg/dL, normal flag, final status. Structurally valid — the result content is fine.</div></div><div class=\"hl7-hint\">Segments are clickable. Compare against a message that filed successfully before 05:12.</div></div>",
q:"Where is the failure?",
opts:[
{t:"PID-3 — the patient identifier format must have changed, so Epic can't find the patient.",c:0},
{t:"OBX-5 — malformed result values are being rejected by filing validation.",c:0},
{t:"ORC-3 / OBR-3 — the filler order number prefix changed from SHC- to SHCB-, so Epic can't match results back to their orders.",c:1}],
good:"<span class='fb-tag'>Correct — the placer/filler handshake broke</span><p>Epic files an unsolicited result by matching the <strong>filler order number</strong> (ORC-3/OBR-3) back to the order it placed. Yesterday's messages carried <strong>SHC-</strong> prefixes; at 05:12 they became <strong>SHCB-</strong>, and the match fails. Patient lookup succeeded (the error log said so) and the OBX result content is structurally valid — the break is order matching.</p>",
bad:"<span class='fb-tag'>Look again at the error text</span><p>The error says <strong>\"no matching order found for filler order number\"</strong> — and the log confirmed the patient MRN verified fine, so PID isn't it. The OBX values are structurally valid. The failure is in <strong>ORC-3/OBR-3</strong>: the filler prefix changed from SHC- to SHCB- at exactly 05:12, breaking the result-to-order match.</p>",
nxt:"Find the root cause →"},
{tag:"Phase 4 — Root cause & fix",title:"08:05 — why did the prefix change at 05:12?",
body:"<p class=\"body\">You call the lab IT lead. One question: \"Did anything change in Beaker overnight?\" The answer comes fast — a scheduled LIS maintenance package was applied at 05:00 that consolidated specimen numbering across the new satellite lab, changing the filler ID prefix from <strong>SHC-</strong> to <strong>SHCB-</strong>. The change went through <strong>lab's</strong> change control, but the interface team was never on the notification list.</p><div class=\"term\"><div class=\"term-bar\"><span class=\"dot r\"></span><span class=\"dot y\"></span><span class=\"dot g\"></span><span class=\"term-title\">change-log — LIS maintenance window</span></div><div class=\"term-body\"><span class=\"tk-d\">CHG0031187 · Beaker LIS maintenance · window 05:00–05:15</span>\n<span class=\"tk-ok\">✓ applied 05:09</span>  specimen numbering consolidation (satellite lab go-live)\n<span class=\"tk-w\">⚠ downstream impact assessment: \"none identified\"</span>\n<span class=\"tk-e\">✗ interface team not listed as affected CI stakeholder</span></div></div>",
q:"1,325 results are stuck and growing. How do you fix it?",
opts:[
{t:"Ask lab to roll back the maintenance package — restore the old prefix and the queue drains itself.",c:0},
{t:"File an emergency change: update the interface translation logic to recognize the new SHCB- filler format, validate in TST with lab, then reprocess the deferred queue.",c:1},
{t:"Have HIM and unit clerks manually file the 1,325 results from lab printouts while a permanent fix is designed.",c:0}],
good:"<span class='fb-tag'>Correct — fix forward under emergency change</span><p>Rolling back would break the satellite lab that just went live — trading one incident for another, in a system you don't own. Manual filing of 1,325 results introduces transcription risk worse than the delay. Updating the translation logic under an <strong>emergency change</strong> — validated in TST against replayed real messages first — fixes forward safely, and the deferred queue reprocesses automatically.</p>",
bad:"<span class='fb-tag'>Consider the blast radius</span><p>Rollback breaks the satellite lab that just went live — you'd trade one outage for another, in a system that isn't yours. Manual filing at this volume introduces transcription error risk that's arguably <strong>worse</strong> than the delay. Fix forward: emergency change on the translation logic, validate in TST with replayed messages, promote, then reprocess the deferred queue.</p>",
nxt:"Execute recovery →"},
{tag:"Phase 5 — Recovery & verification",title:"09:20 — the queue drains",
body:"<p class=\"body\">Emergency change approved verbally by the CAB chair at 08:25, documented in ServiceNow. Mapping updated and validated in TST against replayed messages. Fix promoted at 09:05. You reprocess the deferred queue:</p><div class=\"term\"><div class=\"term-bar\"><span class=\"dot r\"></span><span class=\"dot y\"></span><span class=\"dot g\"></span><span class=\"term-title\">bridges-console — reprocess</span></div><div class=\"term-body\"><span class=\"tk-p\">$</span> ifc reprocess --queue deferred --interface BEAKER-ORU-IN\n\nreprocessing 1,325 messages ...\n<span class=\"tk-ok\">✓ filed: 1,321</span>   <span class=\"tk-w\">⚠ manual review: 4</span> (canceled orders — routed to lab workqueue)\n\n<span class=\"tk-p\">$</span> ifc status --interface BEAKER-ORU-IN --last 15m\n 09:05-09:20   recv 118   filed 118   err <span class=\"tk-ok\">0</span>\n<span class=\"tk-ok\">interface healthy · filing latency 1.8s avg</span></div></div><p class=\"body\">You spot-check five charts with the D2 charge nurse — results visible, timestamps correct. Technically, the incident is resolved.</p>",
q:"Before you close the ticket — what has to happen?",
opts:[
{t:"Close it. Queue is at zero, filing is confirmed, SLA met. Documentation can follow later.",c:0},
{t:"Trigger a clinical safety review: identify every critical/abnormal result delayed during the 4-hour window and confirm each was seen and acted on by a provider.",c:1},
{t:"Email the lab manager a summary and ask lab to review their own results at their convenience.",c:0}],
good:"<span class='fb-tag'>Correct — resolution is not safety</span><p>For four hours, results existed that no clinician could see — including criticals. Closing on \"queue is zero\" answers the IT question and ignores the clinical one. The delayed-critical-results review (run with lab and nursing leadership) is what turns \"interface fixed\" into \"<strong>no patient was harmed</strong>\" — and it's what a regulator or safety committee will ask for.</p>",
bad:"<span class='fb-tag'>The clinical question is still open</span><p>The queue at zero answers the IT question, not the clinical one: for four hours, critical results existed that no clinician could see. Before closure, every critical/abnormal result in the window must be identified and <strong>confirmed as seen and acted on</strong>. That review — with lab and nursing leadership — is the difference between \"fixed\" and \"safe.\"</p>",
nxt:"Post-incident →"},
{tag:"Phase 6 — Post-incident",title:"Two days later — the RCA meeting",
body:"<p class=\"body\">The safety review found 23 critical results delayed in the window; all were verified as acknowledged, two required provider follow-up calls. Now you're writing the root cause analysis. The technical fix was easy. The <strong>process failure</strong> is the real finding.</p>",
q:"What's the highest-value corrective action to propose?",
opts:[
{t:"Discipline path: the lab change owner marked \"no downstream impact\" incorrectly — recommend retraining for that individual.",c:0},
{t:"Systemic fix: make the interface team a mandatory stakeholder on any LIS/ancillary change touching identifiers or message formats, and add an automated alert when the interface error rate exceeds threshold — so detection doesn't depend on a nurse calling.",c:1},
{t:"Technical hardening only: build the translation layer to accept any filler prefix format so this class of change can never break filing again.",c:0}],
good:"<span class='fb-tag'>Correct — fix the system, not the person</span><p>Blame-focused RCA guarantees the process gap survives. Prefix-agnostic translation sounds robust but means <strong>silently accepting unannounced upstream changes</strong> — the opposite of controlled interfaces. The systemic fix closes both gaps: mandatory interface-team review on identifier-touching changes (prevention), and automated error-rate alerting (detection). The incident ran undetected for two hours because discovery depended on a nurse.</p>",
bad:"<span class='fb-tag'>That treats a symptom</span><p>Retraining one person leaves the process gap open for the next person. Accepting any prefix format means silently absorbing unannounced upstream changes — uncontrolled interfaces are their own risk. The high-value fix is systemic: <strong>mandatory interface-team stakeholder review</strong> on identifier-touching changes, plus <strong>automated error-rate alerts</strong> so detection never again depends on a nurse calling it in.</p>",
nxt:"View debrief →"}],
debrief:{
timeline:[["05:09","LIS maintenance changes filler order number prefix (<strong>SHC- → SHCB-</strong>). Interface team not notified."],["05:12","Filing failures begin. Error queue grows silently for two hours."],["07:12","Charge nurse reports missing labs. P1 opened — <strong>detection was human, not automated</strong>."],["07:42–07:53","Triage → scope via monitoring → error queue inspection → filler ID mismatch identified in ORC-3/OBR-3."],["08:05–09:05","Root cause confirmed with lab. Emergency change: translation mapping updated, validated in TST, promoted to PRD."],["09:20","1,321 of 1,325 deferred results filed. Chart-level verification with nursing."],["+2 days","Safety review: 23 delayed criticals all acknowledged. RCA drives systemic change-control and monitoring fixes."]],
cards:[
{h:"Skills demonstrated",items:["<strong>HL7 v2 fluency</strong> — ORU^R01 anatomy, placer vs. filler order numbers, result filing logic","<strong>Interface operations</strong> — queue monitoring, error triage, safe reprocessing without message loss","<strong>Change management</strong> — emergency change discipline, TST validation before PRD, CAB documentation","<strong>Cross-team incident command</strong> — lab IT, nursing, CAB, clinical leadership"]},
{h:"Patient-safety framing",items:["An interface outage is a <strong>clinical event</strong>, not an IT event — invisible results are unseen results","Resolution ≠ closure: a <strong>delayed-critical-results review</strong> is mandatory before the ticket closes","Never purge an error queue — every deferred message is a patient's result","Detection must not depend on a nurse noticing — <strong>alert on error-rate thresholds</strong>"]},
{h:"Why the wrong answers fail",items:["<strong>Blind restarts</strong> destroy diagnostic state and fix nothing when the interface is already running","<strong>Rollback</strong> would break the satellite lab that just went live — trading one outage for another","<strong>Manual filing</strong> at volume introduces transcription risk worse than the original delay","<strong>Blaming individuals</strong> in RCA guarantees the process gap survives to fail again"]},
{h:"Interview talking points",items:["\"Placer vs. filler order numbers are the handshake between EHR and LIS — most filing errors live there\"","\"I treat error-queue depth as a patient-safety metric, not a performance metric\"","\"The RCA question is never <em>who</em> — it's <em>what let this reach production unnoticed</em>\""]}]}
},

/* ============ SCENARIO 2: ADT SEQUENCE CRISIS ============ */
{
id:"adt", sev:1, tag:"Interfaces · ADT · System state",
title:"The Hospital That Forgot Where Its Patients Were",
sub:"The ADT feed is lagging 40 minutes behind reality. Transport is arriving at empty beds, the bed board is fiction, and everyone on the bridge has a fast idea that will make it worse. Your job: recover without corrupting state.",
chips:["SEV / P1","ADT · A01/A02/A08","Sequence integrity","Queue operations","Downstream systems"],
ticket:{num:"INC0483177",sev:"P1 — CRITICAL",sevc:"s1",fields:[["Opened","Tue 07:05 AM"],["Caller","Patient Flow / Transport dispatch"],["Assignment group","Clinical Informatics — Interfaces"],["Configuration item","IFC-ADT-OUT (enterprise)"]],
desc:"\"Transport got sent to three rooms this morning where the patient had already moved. Bed board shows patients in beds that are physically empty. <em>Downstream systems are all showing old locations.</em> It's getting worse, not better.\""},
phases:[
{tag:"Phase 1 — Triage",title:"07:05 — the hospital's map is wrong",
body:"<p class=\"body\">Wrong-location data isn't cosmetic: transporters at wrong doors, portable imaging heading to empty beds, and — the quiet nightmare — an emergency response that starts at a stale location. Epic itself shows correct locations; it's every <strong>downstream consumer</strong> of the ADT feed that's living in the past.</p>",
q:"First move?",
opts:[
{t:"Restart the ADT outbound interface — a restart resets whatever is jamming the flow.",c:0},
{t:"Acknowledge, warn patient flow / transport to verify locations by phone for now, and open interface monitoring to characterize the problem: down, erroring, or slow?",c:1},
{t:"Purge messages older than 30 minutes from the queue — old location updates are useless anyway, only current state matters.",c:0}],
good:"<span class='fb-tag'>Correct — characterize before touching</span><p><strong>Down, erroring, or slow are three different incidents.</strong> A restart on a merely-slow interface can drop in-flight messages and buys nothing. And 'old' ADT messages are not useless — each one is a state transition that downstream systems need <em>in order</em>. The interim safety net (verify locations by phone) starts protecting patients while you diagnose — workaround first, root cause second.</p>",
bad:"<span class='fb-tag'>That would deepen the hole</span><p>A restart on a slow-but-running interface risks in-flight messages and fixes nothing. Purging 'old' updates is worse: ADT messages are <strong>sequential state transitions</strong> — deleting the transfer that moved a patient means downstream systems never learn it happened, permanently. Characterize first (down vs erroring vs slow), and put the phone-verification workaround in place while you look.</p>",
nxt:"Open the monitoring →"},
{tag:"Phase 2 — Scope",title:"07:14 — slow, not broken",
body:"<p class=\"body\">The dashboard tells a specific story:</p><div class=\"term\"><div class=\"term-bar\"><span class=\"dot r\"></span><span class=\"dot y\"></span><span class=\"dot g\"></span><span class=\"term-title\">ifc-monitor — IFC-ADT-OUT</span></div><div class=\"term-body\"><span class=\"tk-p\">$</span> ifc status --interface ADT-OUT --since 06:00\n\nINTERFACE   DIR   STATE     QUEUE DEPTH   LATENCY    ERR\nADT-OUT     OUT   <span class=\"tk-ok\">RUNNING</span>   <span class=\"tk-e\">9,412 ▲</span>       <span class=\"tk-e\">41m 30s</span>   <span class=\"tk-ok\">0</span>\n\n<span class=\"tk-d\">inbound message rate:</span>\n 06:00-06:30    240 msg  <span class=\"tk-d\">(normal)</span>\n 06:30-07:00  <span class=\"tk-e\">6,890 msg</span>  <span class=\"tk-w\">◀ 28x normal volume</span>\n 07:00-07:14  <span class=\"tk-e\">3,120 msg</span>\n\n<span class=\"tk-w\">⚠ source analysis: 94% of surge = A08 (update) events</span>\n<span class=\"tk-w\">⚠ originating process: REG-CONVERSION-BATCH (registration data cleanup project)</span></div></div><p class=\"body\">Zero errors. Consumers are healthy. The queue is drowning because a <strong>registration data cleanup batch job</strong> started at 06:30 and is firing thousands of A08 update events into the same pipe that carries live admits and transfers.</p>",
q:"What do you do about the flood?",
opts:[
{t:"Add parallel processing threads on the outbound side — more throughput drains the queue faster.",c:0},
{t:"Find the owner of REG-CONVERSION-BATCH and stop the job now; let the queue drain in order at normal speed.",c:1},
{t:"Fail over to the backup interface node to get a fresh, empty queue.",c:0}],
good:"<span class='fb-tag'>Correct — turn off the tap, don't widen the drain</span><p>The interface isn't broken; it's being flooded by a batch job that should never run against the live pipe during clinical hours. <strong>Stopping the source</strong> is the only fix that doesn't create a new problem: parallelizing ADT risks out-of-order delivery (state corruption), and failover doesn't make 9,412 queued messages disappear — they still must be delivered, in order. Live A01/A02 events resume normal latency as soon as the flood stops.</p>",
bad:"<span class='fb-tag'>Both alternatives create a worse incident</span><p>Parallel processing on ADT is the classic catastrophic 'optimization': messages arriving out of order corrupt downstream state (a transfer applied before its admit), and that damage <em>outlives the incident</em>. Failover doesn't delete the backlog — those 9,412 messages still need ordered delivery. The fix is at the source: <strong>stop the batch job</strong> flooding the pipe, and let the queue drain in sequence.</p>",
nxt:"The bridge call →"},
{tag:"Phase 3 — The pressure moment",title:"07:40 — \"just process the newest first\"",
body:"<p class=\"body\">The batch job is stopped. The queue is draining — in order — but there are still ~7,000 messages ahead of the live ones, and the operations director on the bridge makes a reasonable-sounding demand: <em>\"Patients are moving right now. Skip the backlog and process the newest messages first so the bed board goes current — clean up the old ones later.\"</em> Three people on the call murmur agreement. Everyone is looking at you.</p>",
q:"Your call?",
opts:[
{t:"Do it — current state matters more than history, and the director owns patient flow.",c:0},
{t:"Hold the line: explain that ADT is stateful and out-of-order processing corrupts every downstream system in ways that outlast the incident. Give a concrete drain ETA and keep the phone-verification workaround running until then.",c:1},
{t:"Compromise: process newest-first for the ICU units only, oldest-first for everything else.",c:0}],
good:"<span class='fb-tag'>Correct — sequence integrity is non-negotiable</span><p>This is the moment the incident is actually decided. Newest-first means a downstream system can receive a patient's <em>transfer</em> before their <em>admit</em>, or an update after a discharge it never saw — and each consumer silently builds a corrupted picture that requires manual reconciliation across systems for days. The professional move under pressure isn't just 'no': it's no <strong>with an ETA and a running workaround</strong> — 'queue drains by 08:20, transport verifies by phone until then.' Slow-but-ordered self-heals; fast-but-scrambled becomes next week's mystery tickets.</p>",
bad:"<span class='fb-tag'>That trades 40 minutes of lag for days of corruption</span><p>Out-of-order ADT processing — full or 'compromise' partial — means downstream systems receive transfers before admits and updates after discharges, silently corrupting their state in ways that persist <em>after</em> the queue drains. The director's goal is right; the method destroys it. The answer that holds the room: sequence integrity is non-negotiable, <strong>here's the concrete drain ETA (08:20), and the phone-verification workaround covers the gap</strong>.</p>",
nxt:"Recovery →"},
{tag:"Phase 4 — Recovery & verification",title:"08:25 — queue at zero. Are you done?",
body:"<p class=\"body\">The backlog drained in order, live events are flowing at 1–2 second latency, and the bridge is ready to stand down.</p><div class=\"term\"><div class=\"term-bar\"><span class=\"dot r\"></span><span class=\"dot y\"></span><span class=\"dot g\"></span><span class=\"term-title\">ifc-monitor — IFC-ADT-OUT</span></div><div class=\"term-body\"><span class=\"tk-p\">$</span> ifc status --interface ADT-OUT --last 15m\n\nQUEUE DEPTH: <span class=\"tk-ok\">0</span>    LATENCY: <span class=\"tk-ok\">1.8s</span>    ERR: <span class=\"tk-ok\">0</span>\n<span class=\"tk-ok\">interface healthy · all consumers current</span></div></div>",
q:"What closes the incident?",
opts:[
{t:"Queue at zero with normal latency — that's the definition of resolved. Stand down.",c:0},
{t:"A reality check: spot-verify current census and bed locations against physical reality with nursing coordination, and confirm key downstream systems (bed board, transport, lab) agree with Epic.",c:1},
{t:"Wait 24 hours for complaints; if none arrive, close it.",c:0}],
good:"<span class='fb-tag'>Correct — delivery is not correctness</span><p>Queue-zero proves every message was <em>delivered</em>; it doesn't prove every consumer's state is <em>correct</em> — especially after 90 minutes of chaos that included manual workarounds and phone-verified moves that may not match system state. The reality check (physical beds vs. bed board vs. Epic, with nursing) is the only evidence that the hospital's map matches the hospital again. 'Wait for complaints' outsources verification to future patient-safety events.</p>",
bad:"<span class='fb-tag'>The map might still be wrong</span><p>Queue-zero proves delivery, not correctness — after 90 minutes of lag and manual workarounds, a downstream system can be internally consistent and still wrong. And waiting for complaints means the verification method is 'a future patient-safety event.' Close only after the <strong>reality check</strong>: physical census vs. bed board vs. Epic, spot-verified with nursing coordination.</p>",
nxt:"Post-incident →"},
{tag:"Phase 5 — Post-incident",title:"The RCA — a batch job walked into a live pipe",
body:"<p class=\"body\">Root cause is embarrassingly simple: a well-intentioned registration cleanup project ran a bulk update during morning admission hours, with no throttling, straight into the enterprise ADT feed. Nobody involved thought of it as an 'interface change' — it was 'just a data cleanup.'</p>",
q:"Highest-value corrective action?",
opts:[
{t:"Require the registration project team to get interface-team approval for all future work.",c:0},
{t:"Systemic: an intake rule that bulk jobs touching interfaced data must be scheduled off-hours and rate-throttled, plus queue-depth and latency alerting so the next flood pages the analyst before transport notices.",c:1},
{t:"Increase queue capacity and consumer throughput so the interface can absorb any future surge.",c:0}],
good:"<span class='fb-tag'>Correct — govern the class, alert on the symptom</span><p>The pattern, not the project, is the problem: <em>any</em> bulk operation against interfaced data is an interface event, whether its owner knows it or not. The intake rule (off-hours + throttled) prevents the class; the queue-depth/latency alerting detects whatever slips through — this incident ran 35 minutes before a human noticed, and the human was a transport dispatcher. Capacity upgrades just raise the flood level required to cause the same failure; blanket approval requirements punish one team for a gap every team shares.</p>",
bad:"<span class='fb-tag'>That fixes one team or feeds the next flood</span><p>Singling out this project team leaves every <em>other</em> team's future bulk job unaddressed — the pattern is systemic. And more capacity just raises the surge size needed to recreate the incident. The durable fix is a class-level rule (bulk jobs on interfaced data run off-hours, rate-throttled) plus <strong>queue-depth/latency alerting</strong> — detection took 35 minutes and came from a transport dispatcher, which is the finding that should bother everyone.</p>",
nxt:"View debrief →"}],
debrief:{
timeline:[["06:30","REG-CONVERSION-BATCH begins bulk A08 updates into the live ADT pipe — 28x normal volume."],["06:35–07:05","Queue depth and latency climb silently. <strong>No alerting fires.</strong> Downstream systems fall progressively behind reality."],["07:05","Transport dispatch reports wrong-room sends. P1 opened — detection was a dispatcher, not a monitor."],["07:14","Diagnosis: slow-not-broken. Zero errors, healthy consumers, flooded queue. Source identified."],["07:20","Batch job stopped at the source. Queue begins ordered drain. Phone-verification workaround active."],["07:40","Pressure moment survived: newest-first processing declined with ETA + workaround. Sequence integrity held."],["08:25","Queue zero. Reality check: census and bed board verified against physical units with nursing."],["+1 day","RCA: bulk-job intake rule (off-hours, throttled) + queue-depth/latency alerting adopted."]],
cards:[
{h:"Skills demonstrated",items:["<strong>ADT semantics</strong> — A01/A02/A03/A08 as ordered state transitions, not independent facts","<strong>Queue operations</strong> — down vs erroring vs slow as three distinct incidents with distinct fixes","<strong>Source-level thinking</strong> — stop the flood, don't widen the drain","<strong>Incident leadership under pressure</strong> — holding a technical line against a senior stakeholder, with ETA and workaround in hand"]},
{h:"The one principle",items:["<strong>Sequence integrity beats speed.</strong> Slow-but-ordered recovers by itself; fast-but-scrambled corrupts every consumer and outlives the incident","Out-of-order ADT = transfers before admits = days of manual reconciliation across systems","'Old' messages are not stale data — they are state transitions downstream systems have not yet lived through"]},
{h:"Why the wrong answers fail",items:["<strong>Restart</strong> risks in-flight messages on an interface that was never broken","<strong>Purging old messages</strong> deletes state transitions permanently — downstream never learns those moves happened","<strong>Parallelizing / newest-first</strong> converts a latency incident into a state-corruption incident","<strong>Queue-zero closure</strong> confuses delivery with correctness"]},
{h:"Interview talking points",items:["\"ADT is stateful — my recovery rule is sequence over speed, because scrambled state outlives the outage\"","\"A 'no' under pressure needs an ETA and a workaround attached, or it won't hold the room\"","\"Detection by a transport dispatcher instead of a monitor is the real RCA finding\""]}]}
},

/* ============ SCENARIO 3: COMPROMISED PROVIDER ACCOUNT ============ */
{
id:"phish", sev:2, tag:"Security · IAM · Privacy",
title:"The Provider Who Emailed Everyone at 2 AM",
sub:"A referring clinic reports strange emails from one of your cardiologists. His In Basket has a forwarding rule he never created. Somewhere between phishing and PHI, this ticket stops being an Epic ticket — and you're the analyst holding it.",
chips:["SEV / P2","Account compromise","IAM / InfoSec handoff","Access audit","HIPAA breach process"],
ticket:{num:"INC0483412",sev:"P2 — HIGH",sevc:"s2",fields:[["Opened","Thu 07:20 AM"],["Caller","Help desk (escalation)"],["Assignment group","Clinical Informatics — Access & Security"],["Configuration item","EMP: K44210 (attending, Cardiology)"]],
desc:"\"External clinic called — they got odd emails 'from' Dr. K overnight asking to re-verify a payment portal. Dr. K says he sent nothing and was asleep. Help desk also noticed an <em>In Basket auto-forward rule he says he never created</em>. He's on service today with a full census.\""},
phases:[
{tag:"Phase 1 — Recognition",title:"07:20 — this is not a password ticket",
body:"<p class=\"body\">Read the ingredients: activity the account owner denies, at hours he was asleep, plus a <strong>persistence mechanism</strong> (the In Basket forward rule) someone installed to keep receiving data. A clinical account has access to hundreds of charts. The question is no longer 'how do we fix Dr. K's email' — it's 'who has been inside, since when, and what did they touch.'</p>",
q:"First move?",
opts:[
{t:"Have Dr. K change his password now and delete the forward rule — that cuts off whoever is in.",c:0},
{t:"Treat it as a suspected account compromise: engage the security incident response process immediately, preserve evidence (don't delete the rule yet — screenshot and document it), and coordinate next steps jointly with InfoSec.",c:1},
{t:"Monitor the account quietly for a day to gather evidence about what the attacker does next.",c:0}],
good:"<span class='fb-tag'>Correct — escalate, preserve, coordinate</span><p>The moment compromise is <em>suspected</em>, this becomes a security incident with a defined process — and the analyst's job flips from fixer to first responder: <strong>escalate to InfoSec, preserve evidence, coordinate</strong>. A quick password change alone can tip the attacker while leaving other persistence (sessions, rules, tokens) alive, and deleting the forward rule destroys evidence the investigation needs. You'll act fast — but jointly and in order.</p>",
bad:"<span class='fb-tag'>Incomplete — or actively harmful</span><p>A password change alone leaves active sessions and persistence mechanisms alive and can tip the attacker to burn what access they have — and deleting the rule destroys evidence. 'Monitoring quietly' means <strong>knowingly leaving an attacker inside PHI</strong>, which is indefensible the moment it's discovered. Suspected compromise = security incident: escalate to InfoSec now, preserve evidence, act jointly.</p>",
nxt:"Pull the access picture →"},
{tag:"Phase 2 — Containment",title:"07:35 — the logs confirm it",
body:"<p class=\"body\">Working with InfoSec on a call, you pull the account's recent activity:</p><div class=\"term\"><div class=\"term-bar\"><span class=\"dot r\"></span><span class=\"dot y\"></span><span class=\"dot g\"></span><span class=\"term-title\">access-audit — EMP K44210 · last 12h</span></div><div class=\"term-body\"><span class=\"tk-d\">login history:</span>\n 18:42  workstation CARD-WOW-07     <span class=\"tk-ok\">badge+PIN</span>   <span class=\"tk-d\">(normal pattern)</span>\n <span class=\"tk-e\">02:14  remote — IP 185.220.x.x    password only   ◀ no MFA challenge (legacy portal)</span>\n <span class=\"tk-e\">02:31  In Basket rule created: auto-forward → external address</span>\n <span class=\"tk-e\">02:33–03:58  chart access: 47 records opened, sequential pattern</span>\n <span class=\"tk-w\">04:02  outbound messages sent to referring-clinic contact list</span>\n\n<span class=\"tk-d\">current state: 2 active sessions (1 remote)</span></div></div><p class=\"body\">Remote login, no MFA, a persistence rule, 47 charts opened in a scraping pattern, and <strong>one of those sessions is still alive</strong>.</p>",
q:"Containment — what's the right shape?",
opts:[
{t:"Coordinated containment now: disable the account, terminate all active sessions, revoke tokens/remote access, remove the forward rule (evidence already preserved), and reset credentials — as one synchronized action with InfoSec.",c:1},
{t:"Remove the forward rule and block the external IP, but leave the account active so Dr. K's clinical day isn't disrupted.",c:0},
{t:"Terminate the remote session only — the badge login is legitimate, so the account itself is fine.",c:0}],
good:"<span class='fb-tag'>Correct — containment is atomic or it isn't containment</span><p>Piecemeal moves (kill one session, block one IP) leave the attacker's other footholds alive and signal that you're onto them — credentials are burned, so <strong>everything rotates at once</strong>: account disabled, all sessions dead, tokens revoked, rule removed (after evidence capture), credentials reset. Yes, this takes Dr. K offline mid-census — that's a real clinical cost, which is why the <em>next</em> phase exists. Security first, continuity immediately after, in that order.</p>",
bad:"<span class='fb-tag'>Partial containment is a notified attacker</span><p>Blocking one IP or killing one session while the account stays live leaves every other foothold (tokens, other sessions, the credentials themselves) usable — and tips the attacker to move faster. Compromised credentials are burned, period: <strong>atomic containment</strong> — disable, kill all sessions, revoke, reset — as one synchronized action with InfoSec. The clinical disruption is real, and it's the next problem to solve, not a reason to leave the door open.</p>",
nxt:"He's on service with 14 patients →"},
{tag:"Phase 3 — Clinical continuity",title:"08:10 — the attending needs a chart, now",
body:"<p class=\"body\">Containment is done. Dr. K is standing at the nurses' station with a full inpatient census, no working login, and rounds starting. The unit is already asking how long. A colleague offers the obvious hallway solution: <em>\"just use my login for this morning.\"</em></p>",
q:"How does Dr. K get back to caring for patients?",
opts:[
{t:"Accept the colleague's offer for the morning — patient care can't wait, and it's temporary.",c:0},
{t:"Expedited verified re-credentialing: identity-proof Dr. K in person (he's physically here), issue new credentials with MFA enrolled, re-enable with enhanced monitoring on the account — target under an hour, with the unit told the ETA.",c:1},
{t:"Keep the account disabled until the full forensic investigation concludes, likely 2–3 days; the service will need coverage arrangements.",c:0}],
good:"<span class='fb-tag'>Correct — fast, verified, and his own identity</span><p>The in-person advantage makes this clean: he's physically present, identity-proofable in minutes, and new credentials with MFA can be live within the hour — <em>with an ETA communicated to the unit</em>, which is what actually manages the clinical pressure. Shared credentials are never the answer: every order signed and chart opened would be legally attributed to the colleague, the audit trail becomes fiction, and it's a HIPAA violation committed to solve a HIPAA incident. And days of lockout punishes patients for the attacker's crime — security that ignores clinical continuity just teaches clinicians to route around security.</p>",
bad:"<span class='fb-tag'>One answer is a violation, the other is a different harm</span><p>Shared login means every order and note that morning is legally attributed to the wrong clinician — the audit trail becomes fiction, and you've committed a HIPAA violation to manage a HIPAA incident. Multi-day lockout makes patients pay for the attacker's crime and teaches the org that reporting compromise is punished. The path is <strong>expedited verified re-credentialing</strong>: he's physically here — identity-proof in person, new credentials + MFA, enhanced monitoring, unit told the ETA. Security and continuity, in that order, both inside the hour.</p>",
nxt:"The 47 charts →"},
{tag:"Phase 4 — The privacy question",title:"09:30 — what did they see?",
body:"<p class=\"body\">The attacker opened <strong>47 patient records</strong> between 02:33 and 03:58 in a sequential, scraping-like pattern. Dr. K is back on service. InfoSec is chasing the phishing infrastructure. But those 47 charts are now a question that belongs to a different discipline entirely.</p>",
q:"What happens with the 47 records?",
opts:[
{t:"Review the accesses yourself: determine which ones look genuinely malicious versus incidental, and report only the concerning subset to privacy.",c:0},
{t:"Hand the complete, contextualized access log for the compromise window to the privacy office as a formal potential-breach referral — they run the HIPAA breach risk assessment and own notification decisions.",c:1},
{t:"No action on the charts — the attacker was after payment-portal phishing targets, not medical records, so the accesses were incidental.",c:0}],
good:"<span class='fb-tag'>Correct — role separation, again</span><p>Unauthorized access to 47 records by a malicious actor is a <strong>potential HIPAA breach by definition</strong>, and breach risk assessment — probability of compromise, notification obligations to patients and HHS, timelines — is the privacy office's legal function, not the analyst's judgment call. Your contribution is evidence quality: the complete access log with context (which records, what was viewed, for how long), delivered securely with chain of custody. Deciding 'they were only phishing, the charts don't count' is a legal determination you're neither authorized nor qualified to make.</p>",
bad:"<span class='fb-tag'>That's a legal determination — and not yours</span><p>Whether those 47 accesses constitute a reportable breach involves regulatory risk assessment, notification obligations, and deadlines — the privacy office's legal function. Pre-filtering 'the concerning subset' yourself biases the evidence; declaring the accesses 'incidental' is a determination that could put the org out of compliance if wrong. The analyst's job is <strong>complete, contextualized, securely delivered evidence</strong> — the full access log for the window, chain of custody documented — and a formal referral. Data from you; determination from privacy.</p>",
nxt:"Post-incident →"},
{tag:"Phase 5 — Post-incident",title:"One week later — the review",
body:"<p class=\"body\">Findings assembled: the phish was a payment-portal lure; Dr. K entered credentials on a convincing fake page; the attacker logged in through a <strong>legacy remote portal that never required MFA</strong>; the In Basket rule was persistence; the 47 charts fed target data for the next round of phishing. Privacy determined notification obligations for a subset of records. Now: corrective actions.</p>",
q:"Highest-value corrective action to champion?",
opts:[
{t:"Mandatory extra security-awareness training for Dr. K, and a notice to medical staff about phishing.",c:0},
{t:"Close the control gaps the incident proved: MFA enforced on every remote access path (kill the legacy exception), alerting on In Basket rule creation and impossible-travel logins, and a review of what a single clinical account can bulk-access.",c:1},
{t:"Block all external/personal email access from the clinical network so phishing links can't be clicked at work.",c:0}],
good:"<span class='fb-tag'>Correct — controls beat blame, detection beats hope</span><p>Dr. K didn't fail — the <em>controls</em> did: a phish that MFA would have stopped, on a portal that skipped MFA, followed by persistence and scraping that <strong>no alert noticed for five hours</strong> (detection came from an external clinic). Training has a place, but humans will always occasionally click; the fixes that scale are structural: close the legacy MFA gap, alert on the attacker behaviors this incident demonstrated (rule creation, anomalous logins), and revisit bulk-access scope. Blocking all external email breaks legitimate clinical communication and doesn't stop phishing on personal devices — theater, not control. This corrective-action list, incidentally, reads exactly like an IAM analyst's job description.</p>",
bad:"<span class='fb-tag'>That retrains the human and leaves the doors open</span><p>Training Dr. K treats the control failure as a personal failure — but the phish worked because a legacy portal skipped MFA, and the attacker then operated for five hours with <strong>zero alerting</strong> (an external clinic detected it, not the SOC). Humans will occasionally click; controls must assume it. Email blocking is theater that breaks clinical communication. The durable fixes: MFA on every remote path, alerts on rule-creation and anomalous logins, bulk-access scope review — close the gaps the incident proved exist.</p>",
nxt:"View debrief →"}],
debrief:{
timeline:[["~01:50","Dr. K enters credentials on a phishing page (payment-portal lure) — likely from a personal device."],["02:14","Attacker logs in via legacy remote portal — <strong>no MFA challenge</strong>. No alert fires."],["02:31","Persistence installed: In Basket auto-forward rule to external address."],["02:33–03:58","47 patient records opened in a scraping pattern. No alert fires."],["04:02","Outbound phishing sent to referring-clinic contacts from the trusted account."],["07:20","External clinic reports odd emails. <strong>Detection was a business partner, not a control.</strong>"],["07:35–08:00","Evidence preserved, then atomic containment with InfoSec: disable, kill sessions, revoke, reset."],["08:10–09:00","Clinical continuity: in-person identity proofing, new credentials + MFA, re-enabled with monitoring inside the hour."],["09:30","Formal potential-breach referral: full contextualized access log to privacy office."],["+1 week","Corrective actions: MFA on all remote paths, behavioral alerting, bulk-access review."]],
cards:[
{h:"Skills demonstrated",items:["<strong>Incident recognition</strong> — reading denied activity + persistence mechanism as compromise, not a password problem","<strong>Coordinated containment</strong> — atomic disable/kill/revoke/reset, evidence preserved first","<strong>Security–clinical balance</strong> — verified re-credentialing inside the hour instead of shared logins or multi-day lockouts","<strong>Privacy process fluency</strong> — formal breach referral with evidence chain, role separation held"]},
{h:"The bridge to security work",items:["This ticket <strong>is</strong> the CSA → IAM → Security Analyst path in miniature: auth chains, MFA coverage, persistence detection, access auditing","The corrective-action list (MFA enforcement, behavioral alerting, access scope review) is an IAM analyst's daily work","Clinical context is the differentiator: knowing <em>why</em> the account can't stay down for three days is what pure-security candidates lack"]},
{h:"Why the wrong answers fail",items:["<strong>Password-change-only</strong> leaves sessions and persistence alive and tips the attacker","<strong>Quiet monitoring</strong> = knowingly leaving an attacker inside PHI","<strong>Shared logins</strong> commit a HIPAA violation to manage a HIPAA incident — the audit trail becomes fiction","<strong>Analyst-adjudicated breach scope</strong> is a legal determination made without authority"]},
{h:"Interview talking points",items:["\"Denied activity plus a persistence mechanism is compromise until proven otherwise — and containment is atomic or it isn't containment\"","\"Security that ignores clinical continuity teaches clinicians to route around security — my job is both, in order, fast\"","\"Five hours of attacker dwell time with zero alerts is the real finding — detection came from outside the building\""]}]}
}
];
